def sft_batches(cases, steps, batch_size, seed):
    fams={}
    for c in cases: fams.setdefault(c['family'],[]).append(c)
    rng=random.Random(seed); sched=[]; needed=steps*batch_size; keys=list(fams)
    while len(sched)<needed:
