_CAL_MDAYS = [31,28,31,30,31,30,31,31,30,31,30,31]
def _cal_isleap(year):
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)
def _cal_mdays(year, month):
    if month == 2 and _cal_isleap(year):
        return 29
    return _CAL_MDAYS[month - 1]
def _cal_weekday(year, month, day):
    shift = [0,3,2,5,0,3,5,1,4,6,2,4]
    y = year
    if month < 3:
        y = y - 1
    sun0 = (y + y//4 - y//100 + y//400 + shift[month-1] + day) % 7
