def _drop_import(src, module):
    out = []
    for line in src.split("\n"):
        stripped = line.strip()
        if re.match(r"^from\s+%s\s+import\s" % re.escape(module), stripped):
            continue
        m = re.match(r"^import\s+(.+)$", stripped)
        if m:
            names = [p.strip() for p in m.group(1).split(",")]
            if module in [n.split(" as ")[0].strip() for n in names]:
                keep = [n for n in names if n.split(" as ")[0].strip() != module]
                indent = " " * (len(line) - len(line.lstrip()))
                if keep:
                    out.append(indent + "import " + ", ".join(keep))
                continue
        out.append(line)
    return "\n".join(out)

def rule_calendar(src):
    if "calendar" not in src:
        return None
    body = src
    need = False
    for attr, helper in (("monthrange", "_cal_monthrange"), ("isleap", "_cal_isleap"),
                         ("weekday", "_cal_weekday")):
        new = re.sub(r"\bcalendar\.%s\b" % attr, helper, body)
        if new != body:
            body, need = new, True
    for attr, const in (("month_name", "_CAL_MONTH_NAME"), ("month_abbr", "_CAL_MONTH_ABBR"),
                        ("day_name", "_CAL_DAY_NAME"), ("day_abbr", "_CAL_DAY_ABBR")):
        new = re.sub(r"\bcalendar\.%s\b" % attr, const, body)
        if new != body:
            body, need = new, True
    if re.search(r"\bcalendar\.", body):
        return None  # an attribute this rule does not serve
    body = _drop_import(body, "calendar")
    if body == src:
        return None
    return (PRELUDE_CAL if need else "") + body

def run(binary, program, spec, workdir):
    for name, text in (spec.get("files") or {}).items():
        if "/" in name or name.startswith("."):
            return None
        (workdir / name).write_text(text, encoding="utf-8")
    try:
        return subprocess.run([binary, "-I", "-c", program] + list(spec.get("argv") or []),
            input=(spec.get("stdin") or ""), capture_output=True, text=True,
            cwd=str(workdir), timeout=10.0)
    except Exception:
        return None

def verify(python, engine, program, row, workdir):
    for spec, want in zip(row["inputs"], row["expected"]):
        for p in workdir.iterdir(): p.unlink()
        got = run(python, program, spec, workdir)
        if got is None or got.returncode != 0 or got.stderr.strip() or got.stdout != want:
            return False, "cpython-mismatch"
        for p in workdir.iterdir(): p.unlink()
        nat = run(engine, program, spec, workdir)
        if nat is None or nat.returncode != 0:
            return False, "still-refused:%s" % (nat.stderr.strip()[:80] if nat else "None")
        if nat.stdout != want:
            return False, "engine-mismatch"
    return True, None

