_DT_MDAYS = [0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
def _dt_leap(y):
    return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)
def _dt_dfc(y, m, d):
    yy = y
    if m <= 2:
        yy = yy - 1
    era = yy // 400
    yoe = yy - era * 400
    if m > 2:
        mp = m - 3
    else:
        mp = m + 9
    doy = (153 * mp + 2) // 5 + d - 1
    doe = yoe * 365 + yoe // 4 - yoe // 100 + doy
    return era * 146097 + doe - 719468
def _dt_cfd(z):
    zz = z + 719468
    era = zz // 146097
    doe = zz - era * 146097
    yoe = (doe - doe // 1460 + doe // 36524 - doe // 146096) // 365
    y = yoe + era * 400
    doy = doe - (365 * yoe + yoe // 4 - yoe // 100)
    mp = (5 * doy + 2) // 153
    d = doy - (153 * mp + 2) // 5 + 1
    if mp < 10:
        m = mp + 3
    else:
        m = mp - 9
    if m <= 2:
        y = y + 1
    return (y, m, d)
def _dt_date(y, m, d):
    if y < 1 or y > 9999:
        raise ValueError("year %d is out of range" % y)
    if m < 1 or m > 12:
        raise ValueError("month must be in 1..12")
    n = _DT_MDAYS[m]
    if m == 2 and _dt_leap(y):
        n = 29
    if d < 1 or d > n:
        raise ValueError("day is out of range for month")
    return _dt_dfc(y, m, d)
def _dt_year(z):
    return _dt_cfd(z)[0]
def _dt_month(z):
    return _dt_cfd(z)[1]
def _dt_day(z):
    return _dt_cfd(z)[2]
def _dt_yday(z):
    return z - _dt_dfc(_dt_cfd(z)[0], 1, 1) + 1
def _dt_dig(c):
    return '0' <= c <= '9'
def _dt_mo_alts(s, i):
    out = []
    n = len(s)
    if i + 2 <= n and s[i] == '1' and '0' <= s[i + 1] <= '2':
        out.append((int(s[i:i + 2]), i + 2))
    if i + 2 <= n and s[i] == '0' and '1' <= s[i + 1] <= '9':
        out.append((int(s[i:i + 2]), i + 2))
    if i < n and '1' <= s[i] <= '9':
        out.append((int(s[i]), i + 1))
    return out
def _dt_dy_alts(s, i):
    out = []
    n = len(s)
    if i + 2 <= n and s[i] == '3' and '0' <= s[i + 1] <= '1':
        out.append((int(s[i:i + 2]), i + 2))
    if i + 2 <= n and '1' <= s[i] <= '2' and _dt_dig(s[i + 1]):
        out.append((int(s[i:i + 2]), i + 2))
    if i + 2 <= n and s[i] == '0' and '1' <= s[i + 1] <= '9':
        out.append((int(s[i:i + 2]), i + 2))
    if i < n and '1' <= s[i] <= '9':
        out.append((int(s[i]), i + 1))
    if i + 2 <= n and s[i] == ' ' and '1' <= s[i + 1] <= '9':
        out.append((int(s[i + 1]), i + 2))
    return out
def _dt_strptime_ymd(s):
    n = len(s)
    y = 0
    mv = 0
    dv = 0
    ok = False
    if n >= 5 and s[4] == '-' and _dt_dig(s[0]) and _dt_dig(s[1]) and _dt_dig(s[2]) and _dt_dig(s[3]):
        y = int(s[0:4])
        for cand in _dt_mo_alts(s, 5):
            mv = cand[0]
            j = cand[1]
            if j < n and s[j] == '-':
                for cd in _dt_dy_alts(s, j + 1):
                    if cd[1] == n:
                        dv = cd[0]
                        ok = True
                        break
            if ok:
                break
    if not ok:
        raise ValueError("time data %r does not match format '%%Y-%%m-%%d'" % s)
    return _dt_date(y, mv, dv)

