# ---- the dead-import rule, measured separately ----
import ast
def rule_dead_import(src, module="datetime"):
    """The refused import is never used. Nothing is deleted but the import."""
    if module not in src:
        return None
    try:
        tree = ast.parse(src)
    except SyntaxError:
        return None
    bound = set()
    for n in ast.walk(tree):
        if isinstance(n, ast.Import):
            for a in n.names:
                if a.name.split(".")[0] == module:
                    bound.add(a.asname or a.name)
        elif isinstance(n, ast.ImportFrom):
            if n.module == module:
                for a in n.names:
                    bound.add(a.asname or a.name)
    if not bound:
        return None
    for n in ast.walk(tree):
        if isinstance(n, ast.Name) and n.id in bound and not isinstance(n.ctx, ast.Store):
            return None
        if isinstance(n, ast.Attribute) and isinstance(n.value, ast.Name) and n.value.id in bound:
            return None
    out = _drop_import(src, module)
    if out == src:
        return None
    return out

