from pipeline import stats
def het_pilot(nfam,ncase,mean,spread,seed=11):
    rng=random.Random(seed)
    rates=[min(1.0,max(0.0,rng.gauss(mean,spread))) for _ in range(nfam)]
    p={}
    for i in range(ncase):
        f=i%nfam
        p["c%d"%i]={"family":"f%d"%f,"scores":[1 if rng.random()<rates[f] else 0 for _ in range(16)]}
    return p
def run(name,pl,sizes):
    out=stats.power_curve_clustered(pl,16,mde=0.03,deltas=(0.0,0.05,0.08,0.10),
                                    sizes=sizes,trials=60,resamples=200,seed=7)
    print("=== %s [%s]"%(name,out["pilot"]))
    for r in out["rows"]:
        print("   %-13s delta=%4.2f N=%-4d power=%5.0f%%  macro=%+.4f capped=%.2f"%(
            r["shape"],r["delta"],r["N"],100*r["power"],r["mean_macro_effect"],r["capped"]))
run("E het 18 fam / 597 cases, family rates ~N(0.69,0.25)", het_pilot(18,597,0.69,0.25), (597,))
