import re, sys

def lit(key, body, indent=4):
    lines = body.strip("\n").split("\n")
    pad = " " * (indent + 4)
    out = ['%s"%s": (' % (" " * indent, key)]
    for i, l in enumerate(lines):
        esc = l.replace("\\", "\\\\").replace('"', '\\"')
        tail = ")," if i == len(lines) - 1 else ""
        out.append('%s"%s\\n"%s' % (pad, esc, tail))
    return "\n".join(out)

src = open('/tmp/cse/pre_cal.py').read() + open('/tmp/cse/pre_dt.py').read()
blocks = {}
def take(names, text):
    # pull out top-level defs / assignments by name, in source order
    chunks = []
    cur, curname = [], None
    for line in text.split("\n"):
        m = re.match(r"^(?:def\s+(\w+)|(_[A-Z][A-Z_]*)\s*=)", line)
        if m:
            if curname: chunks.append((curname, "\n".join(cur)))
            curname = m.group(1) or m.group(2); cur = [line]
        elif curname is not None:
            cur.append(line)
    if curname: chunks.append((curname, "\n".join(cur)))
    d = dict(chunks)
    return "\n".join(d[n].rstrip("\n") for n in names)

